edits.after:
_keydown(event) {
  if (!([ARROW_LEFT_KEY, ARROW_RIGHT_KEY, ARROW_UP_KEY, ARROW_DOWN_KEY].includes(event.key))) {
    return
  }

  event.stopPropagation()// stopPropagation/preventDefault both added to support up/down keys without scrolling the page
  event.preventDefault()
  const isNext = [ARROW_RIGHT_KEY, ARROW_DOWN_KEY].includes(event.key)
  const children = this._getChildren()
  let index = children.indexOf(event.target)
  if (index === -1) {
    index = isNext ? 0 : children.length - 1
  }
  let nextIndex = index
  do {
    nextIndex = isNext ? (nextIndex + 1) % children.length : (nextIndex - 1 + children.length) % children.length
    const candidate = children[nextIndex]
    if (!isDisabled(candidate)) {
      break
    }
    if (nextIndex === index) {
      break
    }
  } while (true)
  const nextActiveElement = children[nextIndex]
  Tab.getOrCreateInstance(nextActiveElement).show()
}
